  {codigo:'MANUTENCAO_PREDIAL', nomes:['Manutenção Predial','Manutencao Predial'], termos:['manutencao predial','manutenção predial','pintura','pintar','tinta','retoque','parede suja','descascando','mofo','construcao','construção','alvenaria','parede','reboco','piso','ceramica','cerâmica','cimento','argamassa','concreto','calcada','calçada','muro','rachadura','infiltracao','infiltração','telha','goteira','forro','serralheria','solda','portao','portão','grade','ferro','metal','estrutura metalica','estrutura metálica','corrimao','corrimão','alambrado']}
];
