function findCategoria(nomes) {
  for (const nome of nomes) {
    const n = norm(nome);
    let found = cats.find(c => c.norm === n);
    if (found) return found;
    found = cats.find(c => c.norm.includes(n) || n.includes(c.norm));
    if (found) return found;
